#!/bin/bash
# RPD-RECO data-free prologue, rerun (the director's go, 2026-11-07, after coverage-5b-audit closed C1-C4 on #848):
# Codex2's fd_rpd_reco_prologue_connect.sh at #848's head 2cfa1a1e, from a fresh clone, on a login node at 0 node-h.
# In this connect, in order:
#   1. the COV2D fence (squeue cov2d-* must be empty, else STOP), recorded;
#   2. the fresh clone's HEAD and porcelain;
#   3. the resolved policy config (whole baseline_flux, $UNI and the CFS CV added to COV2D's protected set), written
#      from this script and checked against its sha256;
#   4. the strace probe;
#   5. the director's C4a probe, data-free: set -euo pipefail; check-mat-setup as the wrapper runs it; set +u; source
#      the same setup_salloc_env.sh; set -u; then the shell flags;
#   6. the prologue wrapper.
# Everything is under the literal root /dev/shm/limres-rpd-prologue2-20261107 (refused if it exists). The run directory
# is left for the tar-back connect, and a third connect removes the root by its literal path. Launched from a /dev/shm
# copy of itself ($1), which it deletes.
SELF=$1
S=2cfa1a1ea6f474471dda43bb95d292edea2a73e3
CFG_SHA=fe1ce7830d9c230dda6cc1c6c569113b58c425c575d97ffc5d9fc12e994370eb
MAT_PYTHON=/global/homes/j/josephrb/.conda/envs/root_6_28/bin/python3
MATENV=/pscratch/sd/j/josephrb/MINERvA-OmniFold/setup_salloc_env.sh
finish() { echo "== rpd-prologue2 rc=$1 $(date -u +%FT%TZ)"; rm -f -- "$SELF"; exit "$1"; }
case "$(hostname)" in login*) ;; *) echo "STOP: not a login node: $(hostname)"; finish 9 ;; esac
[ ! -e /dev/shm/limres-rpd-prologue2-20261107 ] || { echo "STOP: /dev/shm/limres-rpd-prologue2-20261107 exists"; finish 9; }
echo "node $(hostname) $(date -u +%FT%TZ)"
echo "connect script sha256 $(sha256sum "$SELF" | cut -d' ' -f1)"
echo "== 1. COV2D fence, immediately before (must be empty)"
fence=$(squeue -u josephrb -h -o '%i|%j|%T|%M|%l'); frc=$?
hits=$(printf '%s\n' "$fence" | awk -F'|' '$2 ~ /^cov2d-/')
echo "squeue rc=$frc; cov2d-* rows: [$hits]"
[ "$frc" -eq 0 ] && [ -z "$hits" ] || { echo "STOP: the fence is not clear"; finish 3; }
mkdir /dev/shm/limres-rpd-prologue2-20261107 || finish 9
echo "== 2. fresh clone at $S"
git clone --quiet --filter=blob:none --no-checkout https://github.com/josephbaileyy/MINERvA-OmniFold.git   /dev/shm/limres-rpd-prologue2-20261107/repo || { echo "STOP: clone failed"; finish 5; }
git -C /dev/shm/limres-rpd-prologue2-20261107/repo -c advice.detachedHead=false checkout --quiet "$S" || { echo "STOP: checkout failed"; finish 5; }
head=$(git -C /dev/shm/limres-rpd-prologue2-20261107/repo rev-parse HEAD)
porc=$(git -C /dev/shm/limres-rpd-prologue2-20261107/repo status --porcelain | wc -l)
echo "HEAD $head; porcelain lines $porc"
[ "$head" = "$S" ] && [ "$porc" -eq 0 ] || { echo "STOP: the clone is not $S clean"; finish 5; }
for f in nd-unfolding/fd_rpd_reco_prologue_connect.sh nd-unfolding/fd_rpd_reco_prologue.py nd-unfolding/fd_rpd_reco.py nd-unfolding/fd_rpd_reco_custody.py nd-unfolding/fd_rpd_inputs.py; do
  echo "blob $(git -C /dev/shm/limres-rpd-prologue2-20261107/repo rev-parse "$S:$f") sha256 $(sha256sum "/dev/shm/limres-rpd-prologue2-20261107/repo/$f" | cut -d' ' -f1) $f"
done
echo "== 3. the resolved policy config"
printf '%s' '' | base64 -d > /dev/shm/limres-rpd-prologue2-20261107/policy-config.json
got=$(sha256sum /dev/shm/limres-rpd-prologue2-20261107/policy-config.json | cut -d' ' -f1)
echo "policy config sha256 $got (expected $CFG_SHA)"
[ "$got" = "$CFG_SHA" ] || { echo "STOP: config digest"; finish 5; }
echo "== 4. strace probe"
/usr/bin/strace -f -e trace=open,openat,openat2 -o /dev/shm/limres-rpd-prologue2-20261107/strace-probe.txt /bin/true
echo "strace probe rc=$? lines $(wc -l < /dev/shm/limres-rpd-prologue2-20261107/strace-probe.txt)"
echo "== 5. C4a probe (data-free; its own run dir)"
cat > /dev/shm/limres-rpd-prologue2-20261107/c4a.sh <<'C4A'
set -euo pipefail
"$1" "$2/nd-unfolding/fd_rpd_inputs.py" check-mat-setup --r "$3"
set +u
source "$4"
set -u
echo "flags=$-"
set -o | grep -E "errexit|nounset|pipefail"
C4A
echo "probe script:"; cat /dev/shm/limres-rpd-prologue2-20261107/c4a.sh
bash /dev/shm/limres-rpd-prologue2-20261107/c4a.sh "$MAT_PYTHON" /dev/shm/limres-rpd-prologue2-20261107/repo   /dev/shm/limres-rpd-prologue2-20261107/c4a-run "$MATENV" > /dev/shm/limres-rpd-prologue2-20261107/c4a.out 2>&1
echo "C4a probe rc=$?"; echo "-- C4a output:"; cat /dev/shm/limres-rpd-prologue2-20261107/c4a.out; echo "-- end C4a output"
echo "== 6. the prologue: bash fd_rpd_reco_prologue_connect.sh CHECKOUT CONFIG SHA RUN MAT_PYTHON"
bash /dev/shm/limres-rpd-prologue2-20261107/repo/nd-unfolding/fd_rpd_reco_prologue_connect.sh   /dev/shm/limres-rpd-prologue2-20261107/repo /dev/shm/limres-rpd-prologue2-20261107/policy-config.json "$CFG_SHA"   /dev/shm/limres-rpd-prologue2-20261107/run "$MAT_PYTHON"
p=$?
echo "prologue wrapper rc=$p"
echo "== run directory"
find /dev/shm/limres-rpd-prologue2-20261107/run -maxdepth 2 -printf '%y %s %P\n' 2>&1 | sort -k3
for f in data-free-trace.json worker.stderr.txt worker.stdout.txt; do
  q=/dev/shm/limres-rpd-prologue2-20261107/run/$f
  if [ -f "$q" ]; then echo "== FILE $f sha256 $(sha256sum "$q" | cut -d' ' -f1)"; head -c 6000 "$q"; echo; echo "== END $f"; else echo "== ABSENT $f"; fi
done
finish "$p"
